// Hadith of the day widget for Scriptable — one short hadith per day from Riyad as-Salihin
// (Imam an-Nawawi), bundled offline (source dataset: github.com/AhmedBaset/hadith-json). Picks by
// day-of-year so everyone sees the same hadith each day. Lock-screen families render monochrome.
// Fetched + run by the universal Waqt loader; needs no token (static content).
const HADITHS = [{"t":"Messenger of Allah (ﷺ) passed by a man of the Ansar who was admonishing his brother regarding shyness. Messenger of Allah (ﷺ) said, \"Leave him alone, for modesty is a part of Iman.\" .","n":"Ibn 'Umar","r":1},{"t":"Messenger of Allah (ﷺ) was even shier than a virgin behind her veil. When he saw something which he disliked, we could perceive it on his face..","n":"Abu Sa'id Al-Khudri","r":4},{"t":"Messenger of Allah (ﷺ) said to me, \"O 'Abdullah! Do not be like so-and-so; he used to get up at night for optional prayer but abandoned it later.\".","n":"'Abdullah bin 'Amr bin Al-'as","r":12},{"t":"The Prophet (ﷺ) said, \"It is also charity to utter a good word.\". It is part of a narration that has preceded in its entirety.","n":"Abu Hurairah","r":14},{"t":"Whenever the Prophet (ﷺ) said something, he would repeat his words thrice so that the meanings would be understood fully; and whenever he came upon a group of people, he would greet them, and he would repeat salutation thrice. .","n":"Anas","r":16},{"t":"Messenger of Allah (ﷺ) asked me on the occasion of the Farewell Pilgrimage to tell the people to keep silent, then he (ﷺ) said, \"Do not revert to disbelief after me, chopping the heads of one another.\" .","n":"Jarir bin 'Abdullah","r":18},{"t":"I have never seen Messenger of Allah (ﷺ) laughing so heartily that his uvula could be seen. He used to smile only..","n":"'Aishah","r":23},{"t":"On the occasion of the 'Eid, the Prophet (ﷺ) would proceed to the prayer place taking one route and returning from another. .","n":"Jabir","r":39},{"t":"Messenger of Allah (ﷺ) liked to use his right hand in all matters: in combing his hair and wearing his shoes..","n":"'Aishah","r":41},{"t":"The Prophet (ﷺ) instructed us at the time of washing the dead body of his daughter Zainab (May Allah be pleased with her) to begin with her right side, and from the parts that are washed in Wudu'..","n":"Umm 'Atiyyah","r":43},{"t":"Messenger of Allah (ﷺ) said, \"When you wear your clothes or perform your Wudu', begin with your right side.\".","n":"Abu Hurairah","r":46},{"t":"The Messenger of Allah (ﷺ) was eating with his six Companions when a desert Arab came and ate up the food in two mouthfuls. Messenger of Allah (ﷺ) said, \"Had he mentioned the Name of Allah, it would have sufficed for all of you.\".","n":"'Aishah","r":53},{"t":"The Prophet (ﷺ) asked for sauce and was told that there was nothing except vinegar. He asked for it and began to eat from it saying, \"How excellent is vinegar when eaten as sauce! How excellent is vinegar when eaten as Udm!\".","n":"Jabir","r":57},{"t":"Messenger of Allah (ﷺ) said, \"I do not eat reclining (against a pillow).\" .","n":"Abu Juhaifah Wahb bin 'Abdullah","r":66},{"t":"I saw Messenger of Allah (ﷺ) eating with three fingers (i.e., the thumb, the index finger and the middle finger) and licking them after having finished the food..","n":"Ka'b bin Malik","r":69},{"t":"The Messenger of Allah (ﷺ) said, \"The food of two persons suffices for three persons, and the food of three persons suffices for four persons.\" .","n":"Abu Hurairah","r":75},{"t":"The Messenger of Allah (ﷺ) used to breathe three times in the course of a drink (he used to drink in three gulps). .","n":"Anas","r":77},{"t":"The Messenger of Allah (ﷺ) forbade turning the water-skin upside down and drinking directly from its mouth. .","n":"Abu Sa'id Al-Khudri","r":82},{"t":"The Prophet (ﷺ) prohibited us from breathing into the drinking vessel or blowing in it..","n":"Ibn 'Abbas","r":86},{"t":"'Ali bin Abu Talib (May Allah be pleased with him) arrived at Bab Ar-Rahbah (in Kufah) and drank water in a standing posture. Then he said: \"I saw the Messenger of Allah (ﷺ) doing what you have seen me doing.\".","n":"An-Nazzal bin Sabrah","r":88},{"t":"The Messenger of Allah (ﷺ) said, \"None of you should drink standing; and if any one forgets, he must vomit.\".","n":"Abu Hurairah","r":92},{"t":"The Prophet (ﷺ) visited us and we brought water for him in a brass vessel for his ablution and he performed ablution..","n":"'Abdullah bin Zaid","r":95},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Put on white clothes because they are the best; and use them for shrouding your dead.\".","n":"Ibn 'Abbas","r":99},{"t":"Messenger of Allah (ﷺ) was of medium stature. I saw him wearing a red mantle. I have never seen anything more graceful than that..","n":"Bara'","r":101},{"t":"The Messenger of Allah (ﷺ) entered Makkah on the day of its conquest and he was wearing a black turban..","n":"Jabir","r":104},{"t":"The body of Messenger of Allah (ﷺ) was shrouded in three white Yemeni cotton garments, among which was neither a gown nor a turban..","n":"'Aishah","r":106},{"t":"Out of all garments, the Messenger of Allah (ﷺ) liked the Qamees the best. . Editor's note: The Qamees is a modest, traditional outfit thought to resemble what is now referred to as a thawb.","n":"Umm Salamah","r":109},{"t":"The Prophet (ﷺ) said, \"What is below the ankles of a lower garment is condemned to the Fire (Hell).\".","n":"Abu Hurairah","r":113},{"t":"The Messenger of Allah (ﷺ) said, \"Allah loves to see the sign of His Bounties on his slave.\" .","n":"`Amr bin Shu`aib on the authority of his father and grandfather","r":123},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Silk (clothes) are worn only by he who has no share in the Hereafter.\". Another narration is: \"Who has no share in the Hereafter.\"","n":"'Umar bin Al-Khattab","r":125},{"t":"I saw the Messenger of Allah (ﷺ) holding a piece of gold in his left hand and a silk (cloth) in his right hand. Then he said, \"These two are forbidden for the males of my Ummah.\".","n":"'Ali","r":127},{"t":"The Prophet (ﷺ) prohibited us from eating or drinking from gold or silver utensils and from wearing silk and brocade, or sitting on (anything made from) them..","n":"Hudhaifah","r":129},{"t":"The Messenger of Allah (ﷺ) said, \"Do not ride on saddles made from silk or leopard's skin.\" .","n":"Mu`awiyah","r":131},{"t":"My father said: I was lying down on my belly in the mosque when someone shook me with his foot and said, \"Lying down this way is disapproved by Allah.\" I looked up and saw that it was Messenger of Allah (ﷺ)..","n":"Ya'ish bin Tikhfah Al-Ghifari","r":138},{"t":"I saw Messenger of Allah (ﷺ) sitting in the compound of the Holy Ka'bah, with the thighs against the stomach and arms around his legs..","n":"Ibn 'Umar","r":142},{"t":"Messenger of Allah (ﷺ) passed by me when I was sitting with my left hand behind my back and leaning on my palm. On seeing me in this posture he said, \"Do you sit like those upon whom the Wrath of Allah has descended?\".","n":"Ash-Sharid bin Suwaid","r":144},{"t":"Messenger of Allah (ﷺ) said, \"If someone leaves his seat (for one reason or another) and returns to it, he is better entitled to it.\".","n":"Abu Hurairah","r":146},{"t":"Messenger of Allah (ﷺ) said, \"It is not permissible for a man to separate between two . And in a version narrated by Abu Dawud \"He should not sit between two men without their permission.\"","n":"'Amr bin Shu'aib on the authority of his father and grandfather","r":149},{"t":"I heard Messenger of Allah (ﷺ) saying \"The best assemblies are those in which people make room for one another.\".","n":"Abu Sa'id Al-Khudri","r":151},{"t":"Messenger of Allah (ﷺ) said, \"He who sees me in his dream will see me in his wakefulness (or he (ﷺ) may have said it is as though he has seen me in a state of wakefulness), for Satan does not appear in my form.\".","n":"Abu Hurairah","r":160},{"t":"The Messenger of Allah (ﷺ) passed through the mosque one day and there was a group of women (about ten of them) sitting in the mosque. He raised his hand to offer greetings..","n":"Asma' bint Yazid","r":175},{"t":"I saw the Messenger of Allah (ﷺ) and said: \"Alaikas-Salamu ya Rasulallah! (Upon you be peace, O Messenger of Allah)!\" He said, \"Do not say: 'Alaikas-Salamu (Upon you be peace).' This is the Salam to the dead.\".","n":"Abu Juraiy Al-Hujaimi","r":177},{"t":"The Messenger of Allah (ﷺ) said to me, \"Dear son, when you enter your house, say As- Salamu 'Alaikum to your family, for it will be a blessing both to you and to your family.\".","n":"Anas bin Malik","r":182},{"t":"The Messenger of Allah (ﷺ) said, \"Do not greet the Jews and the Christians before they greet you; and when you meet any one of them on the road, force him to go to the narrowest part of it.\" .","n":"Abu Hurairah","r":187},{"t":"The Prophet (ﷺ) passed by a mixed company of people which included Muslims, polytheists and Jews, and he gave them the greeting (i.e., saying As- Salamu 'Alaikum)..","n":"Usamah bin Zaid","r":189},{"t":"The Messenger of Allah (ﷺ) said, \"Seeking permission to enter (somebody's house) has been prescribed in order to restrain the eyes (from looking at something we are not supposed to look at).\".","n":"Sahl bin Sa'd","r":192},{"t":"I stepped out one night and saw the Messenger of Allah (ﷺ) walking by himself. I began to walk in the moonlit night. He turned round and saw me and asked, \"Who is there?\" I replied: \"Abu Dharr.\".","n":"Abu Dharr","r":196},{"t":"Whenever the Messenger of Allah (ﷺ) sneezed, he would cover his mouth with his hand or a piece of cloth - thereby suppressing the sound..","n":"Abu Hurairah","r":203},{"t":"I asked Anas: \"Did the Companions of the Messenger of Allah (ﷺ) use to shake hands?'' He said: \"Yes.'' .","n":"Abu Khattab Qatadah","r":206},{"t":"The Messenger of Allah (ﷺ) said, \"Two Muslims will not meet and shake hands without having their sins forgiven (by Allah ) before they depart.\".","n":"Al-Bara'","r":208},{"t":"Zaid bin Harithah came to the Messenger of Allah (ﷺ) when he was in my house. Zaid knocked at the door. The Prophet (ﷺ) rose to receive him, trailing his garment. He embraced and kissed him..","n":"'Aishah","r":212},{"t":"The Messenger of Allah (ﷺ) said, \"Visit the sick, feed the hungry, and (arrange for the) release of the captive.'' .","n":"Abu Musa","r":218},{"t":"The Messenger of Allah (ﷺ) visited me during my illness and supplicated, \"O Allah! Cure Sa'd. O Allah! Cure Sa'd. O' Allah! Cure Sa'd.\".","n":"Sa'd bin Abu Waqqas","r":225},{"t":"I visited the Prophet ({ﷺ) while he was suffering. I said: \"(O Messenger of Allah!) You suffer too much.'' He said, \"Yes, I suffer as much as two men of you.'' .","n":"Ibn Mas`ud","r":235},{"t":"The Messenger of Allah (ﷺ) said, \"Exhort your dying men to recite: 'La ilaha illallah' (There is no true god except Allah).\".","n":"Abu Sa'id Al-Khudri","r":239},{"t":"We (womenfolk) were prohibited from accompanying a funeral procession, but we were not compelled (not to do so)..","n":"Umm Atiyyah","r":252},{"t":"The Messenger of Allah (ﷺ) said, \"If a Muslim dies and forty people, who do not associate anything with Allah in worship, participate in the funeral prayer over him, Allah will accept their intercession for him.\".","n":"Ibn 'Abbas","r":254},{"t":"The Prophet (ﷺ) supplicated in course of funeral prayer: \"Allahumma Anta Rabbuha, wa Anta khalaqtaha, wa Anta hadaytaha lil-Islam, wa Anta qabadta ruhaha, wa Anta a'lamu bisirriha wa 'alaniyyatiha, ji'naka shufa'a'a lahu .","n":"Abu Hurairah","r":259},{"t":"I heard the Prophet (ﷺ) saying, \"Hurry up with the dead body (for its burial), for if it is pious, you are speeding it to goodness and if it is otherwise, you are laying an evil off your necks.\" .","n":"Abu Hurairah","r":262},{"t":"After the burial of a dead man, the Prophet (ﷺ) would stand by the grave and say, \"Ask Allah to forgive your brother and supplicate for him for steadfastness because he is being questioned (about his deeds) now.\" .","n":"Abu `Amr (also called Abu `Abdullah and also Abu Laila) from `Uthman bin `Affan","r":267},{"t":"The Messenger of Allah (ﷺ) said, \"Any Muslim who loses three children before they reach the age of maturity, will be granted Jannah by Allah, the Exalted, out of His Mercy for them.\" .","n":"Anas","r":273},{"t":"The Prophet (ﷺ) set out on Thursday for the expedition of Tabuk. He liked to set out on a journey on Thursdays.","n":"Ka'b bin Malik","r":277},{"t":"The Messenger of Allah (ﷺ) said, \"A single rider is (accompanied with) Satan and two riders are (accompanied with) two Satans. Three riders form a group.\".","n":"'Amr bin Shu'aib","r":280},{"t":"The Prophet (ﷺ) said, \"The best number of companions is four; the best detachment is four hundred and the best army is four thousand; and twelve thousand men will not be defeated as a result of smallness of number.\".","n":"Ibn 'Abbas","r":282},{"t":"The Messenger of Allah (ﷺ) said, \"Keep to travelling by night because the earth is folded (traversed more easily) during the night.\".","n":"Anas","r":285},{"t":"The Messenger of Allah (ﷺ) used to lag behind while travelling and urge the weak to walk quickly. He used to take up someone behind him and make supplication for him..","n":"Jabir","r":292},{"t":"Whenever the Prophet (ﷺ) and his army ascended a height, they would proclaim: \"Allahu Akbar (Allah is Greatest),\" and when they climbed down, they would proclaim: \"Subhan Allah (Allah is free from imperfection).\".","n":"Ibn 'Umar","r":297},{"t":"The Messenger of Allah (ﷺ) would not come (back) to his family by night. He used to come in the morning or in the evening (before dark)..","n":"Anas","r":307},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Read the Qur'an, for it will come as an intercessor for its reciters on the Day of Resurrection.\".","n":"Abu Umamah","r":312},{"t":"The Messenger of Allah (ﷺ) said, \"The best amongst you is the one who learns the Qur'an and teaches it.\".","n":"'Uthman bin 'Affan","r":314},{"t":"The Messenger of Allah (ﷺ) said, \"He who does not memorize any part from the Qur'an he is like the ruined house.'' .","n":"Ibn `Abbas","r":321},{"t":"The Messenger of Allah (ﷺ) said: \"The parable of one who knows the Qur'an by heart is as the parable of an owner of hobbled camel. If he remains vigilant, he will retain it; and if he neglects it, it will go away.\".","n":"Ibn 'Umar","r":324},{"t":"I heard the Prophet (ﷺ) reciting Surat Wat-Teen Waz-Zaitun (Chapter 95) during the 'Isha' prayer. I have never heard anyone reciting it in a more beautiful voice than his..","n":"Al-Bara' bin 'Azib","r":327},{"t":"The Messenger of Allah (ﷺ) said, \"Surat Ikhlas is equivalent to one-third of the Qur'an.\".","n":"Abu Hurairah","r":333},{"t":"I heard the Messenger of Allah (ﷺ) saying: \"Do not turn your houses into graveyards. Satan runs away from the house in which Surat Al-Baqarah is recited.\".","n":"Abu Hurairah","r":339},{"t":"I heard my Khalil (the Messenger of Allah (ﷺ)) as saying, \"The adornment of the believer (in Jannah) will reach the places where the water of Wudu' reaches (his body).\".","n":"Abu Hurairah","r":346},{"t":"The Messenger of Allah (ﷺ) said: \"Purification is half the Iman.\".","n":"Abu Malik Al-Ash'ari","r":352},{"t":"The Messenger of Allah (ﷺ) said, \"When you hear the Mu'adhdhin (pronouncing the call to Salat), repeat after him what he says.\".","n":"Abu Sa'id Al-Khudri","r":359},{"t":"The Prophet (ﷺ) said, \"He who says after the Adhan: 'Ash-hadu an la ilaha illallah Wah-dahu la sharika Lahu; wa ash-hadu anna Muhammadan 'abduhu wa Rasuluhu, radhitu Billahi Rabban, wa bi Muhammadin Rasulan, wa bil Islami Dinan .","n":"Sa'd bin Abu Waqqas","r":361},{"t":"The Messenger of Allah (ﷺ) said, \"The similitude of the five (obligatory) Salat is like a river running at the door of one of you in which he takes a bath five times a day.\".","n":"Jabiru","r":364},{"t":"I heard the Messenger of Allah (ﷺ) saying: \"He who performs Salat (prayers) before the rising of the sun and before its setting, will not enter the Hell.\".","n":"Abu Zuhair 'Umarah Ruwaibah","r":369},{"t":"The Messenger of Allah (ﷺ) said, \"He who misses the 'Asr Salat (deliberately), his deeds will be rendered nul and void.\".","n":"Buraidah","r":373},{"t":"The Messenger of Allah (ﷺ) said, \"Convey glad tidings to those who walk to the mosque in the darkness. For they will be given full light on the Day of Resurrection.\".","n":"Buraidah","r":379},{"t":"The Messenger of Allah (ﷺ) said, \"Salat in congregation is twenty-seven times more meritorious than a Salat performed individually.\".","n":"Ibn 'Umar","r":385},{"t":"Messenger of Allah (ﷺ) said, \"That which differentiates us from the disbelievers and hypocrites is our performance of Salat. He who abandons it, becomes a disbeliever.\".","n":"Buraidah","r":400},{"t":"The Messenger of Allah (ﷺ) said, \"If people came to know the blessing of calling Adhan and the standing in the first row, they could do nothing but would draw lots to secure these privileges.\".","n":"Abu Hurairah","r":404},{"t":"The Messenger of Allah (ﷺ) said, \"Keep your rows straight (during Salat in congregation), for keeping the rows straight is part of the perfection of Salat.\".","n":"Anas","r":408},{"t":"The Messenger of Allah (ﷺ) said, \"Allah and His angels invoke blessings upon those who are on the right side of the rows.\".","n":"'Aishah","r":415},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"A house will be built in Jannah for every Muslim who offers twelve Rak'ah of optional Salat other than the obligatory Salat in a day and a night (to seek the Pleasure of Allah).\".","n":"Umm Habibah  the Mother of the Believers","r":418},{"t":"The Prophet (ﷺ) did not attach more importance to any Nawafil prayer than the two Rak'ah of prayer before dawn (Fajr) prayer..","n":"'Aishah","r":422},{"t":"The Messenger of Allah (ﷺ) used to perform two short Rak'ah prayer when it was dawn and the Mu'adhdhin had called Adhan (for the Fajr prayer)..","n":"Hafsah","r":426},{"t":"I observed the Prophet (ﷺ) for one month reciting in the two supererogatory Rak'ah of the Fajr prayer Surat Al-Kafirun (No. 109) .","n":"Ibn 'Umar","r":430},{"t":"The Messenger of Allah (ﷺ) said, \"When anyone of you has performed two of Sunnah before the Fajr prayer, he should lie down on his right side.\".","n":"Abu Hurairah","r":433},{"t":"The Prophet (ﷺ) never omitted four Rak'ah supererogatory prayer before Zuhr prayers..","n":"'Aishah","r":435},{"t":"The Prophet (ﷺ) said, \"May Allah have mercy on a man who performs four Rak'ah before the 'Asr prayer.\".","n":"Ibn 'Umar","r":441},{"t":"The Prophet (ﷺ) said, \"Perform two Rak'ah before Maghrib prayer.\" He (ﷺ) repeated it twice; when repeating it for the third time he added: \"He who may so wish.\".","n":"'Abdullah bin Mughaffal","r":443},{"t":"The Messenger of Allah (ﷺ) said, \"If anyone of you performs the Friday prayer, he should perform four Rak'ah (Sunnah) after it.\".","n":"Abu Hurairah","r":447},{"t":"The Prophet (ﷺ) said, \"O people! perform your (voluntary) Salat (prayers) in your homes because the best Salat of a man is the one he performs at home, except the obligatory Salat.\".","n":"Zaid bin Thabit","r":449},{"t":"The Prophet (ﷺ) said, \"Make Witr prayer the last of your Salat at night.\".","n":"Ibn 'Umar","r":455},{"t":"The Prophet (ﷺ) used to perform his voluntary prayer at night (i.e., Tahajjud prayer) while she was sleeping in front of him; and when the Witr prayer was yet to be observed, he would awaken her to perform her Witr prayer..","n":"'Aishah","r":457},{"t":"The Messenger of Allah (ﷺ) used to perform four Rak'ah of Duha prayer (at the forenoon) and would add to them whatever Allah wished..","n":"'Aishah","r":462},{"t":"The Messenger of Allah (ﷺ) said, \"When anyone of you enters the mosque, he should perform two Rak'ah (of voluntary prayer) before sitting.\".","n":"Abu Qatadah","r":465},{"t":"The Messenger of Allah (ﷺ) said, \"The best day on which the sun has risen is Friday. On that day Adam was created, he was admitted to Jannah, and he was expelled therefrom.\".","n":"Abu Hurairah","r":468},{"t":"The Messenger of Allah (ﷺ) said, \"Taking a bath (before coming to Friday prayers) is obligatory on every adult.\".","n":"Abu Sa'id Al-Khudri","r":473},{"t":"The Messenger of Allah (ﷺ) said, \"Among the best of your days is Friday. On that day pray to Allah to exalt my mention frequently, for your such supplications are presented to me.\".","n":"Aus bin Aus","r":479},{"t":"The Messenger of Allah (ﷺ) said to me, \"Do not be like so-and-so O 'Abdullah! He used to pray during the night, then stopped the practice.\".","n":"'Abdullah bin 'Amr bin Al-'As","r":484},{"t":"The Prophet (ﷺ) said, \"O people, promote the greetings, feed (the poor and needy) and perform Salat when others are asleep so that you will enter Jannah safely.\".","n":"'Abdullah bin Salam","r":487},{"t":"The Prophet (ﷺ) performed the night prayer in pairs (i.e., Rak'ah) and made it odd number by observing one Rak'ah (as Witr)..","n":"Ibn 'Umar","r":490},{"t":"The Messenger of Allah (ﷺ) was asked: \"Which Salat is the best?\" He replied, \" The best Salat is that in which Qiyam (the duration of standing) is longer.\".","n":"Jabir","r":497},{"t":"Whenever the Messenger of Allah (ﷺ) stood for Salat at night, he would start his prayer with two brief Rak'ah..","n":"'Aishah","r":501},{"t":"The Messenger of Allah (ﷺ) said, \"When a man awakens his wife during the night and they both perform two Rak'ah Salat together, they are recorded among the men and women who celebrate remembrance of Allah.\".","n":"Abu Sa'id and Abu Hurairah","r":505},{"t":"The Messenger of Allah (ﷺ) said, \"He who observes optional prayer (Tarawih prayers) throughout Ramadan, out of sincerity of Faith and in the hope of earning reward will have his past sins pardoned.\".","n":"Abu Hurairah","r":508},{"t":"The Messenger of Allah (ﷺ) used to seclude himself (in the mosque) during the last ten nights of Ramadan. He would say, \"Search for Lailat-ul-Qadr (Night of Decree) in the last ten nights of Ramadan.\".","n":"'Aishah","r":512},{"t":"When the last ten nights (of Ramadan) would begin, the Messenger of Allah (ﷺ) would keep awake at night (for prayer and devotion), awaken his family and prepare himself to be more diligent in worship..","n":"'Aishah","r":514},{"t":"The Messenger of Allah (ﷺ) said, \"I stress upon you to use Miswak (tooth- stick).\".","n":"Anas","r":520},{"t":"I came to the Prophet (ﷺ) once and noticed the tip of Miswak (tooth-stick) on his tongue..","n":"Abu Musa Al-Ash'ari","r":522},{"t":"The Prophet (ﷺ) said, \"There are five acts which conform to the pure nature: Circumcision, removing of the pubic hair, clipping the nails, plucking the underarm hair and trimming the moustache.\".","n":"Abu Hurairah","r":524},{"t":"I pledged allegiance to the Prophet (ﷺ) to establish Salat, to pay the Zakat and to have the welfare of every Muslim at heart..","n":"Jarir bin 'Abdullah","r":534},{"t":"The Prophet (ﷺ) said, \"He who observes fasting during the month of Ramadan with Faith while seeking its reward from Allah, will have his past sins forgiven.\".","n":"Abu Hurairah","r":540},{"t":"The Messenger of Allah (ﷺ) said, \"Observe Saum (fast) on sighting the crescent and terminate it on sighting it (the new moon), but if the sky is cloudy before you, then complete the number (thirty days) of the month.\".","n":"Abu Hurairah","r":542},{"t":"The Messenger of Allah (ﷺ) said, \"When there comes the middle of Sha'ban, don't observe Saum (fasting).\".","n":"Abu Hurairah","r":547},{"t":"The Messenger of Allah (ﷺ) said, \"Eat Suhur (predawn meal). Surely, there is a blessing in Suhur.\".","n":"Anas","r":550},{"t":"The Messenger of Allah (ﷺ) had two Mu'adhdhin: Bilal and Ibn Umm Maktum (May Allah be pleased with them). The Messenger of Allah (ﷺ) said, \"Bilal proclaims Adhan .","n":"Ibn 'Umar","r":552},{"t":"The Messenger of Allah (ﷺ) said, \"People will continue to adhere to good as long as they hasten to break the Saum (fasting).\".","n":"Sahl bin Sa'd","r":554},{"t":"I heard the Prophet (ﷺ) saying, \"When one of you breaks his Saum (fasting), let him break it on dates; if he does not have any, break his fast with water for it is pure.\".","n":"Salman bin 'Amir","r":559},{"t":"The Prophet (ﷺ) said, \"If any one of you forgetfully eats or drinks (while observing fasting) he should complete his Saum (fasting), for Allah has fed him and given him to drink.\".","n":"Abu Hurairah","r":563},{"t":"The Messenger of Allah (ﷺ) would wake during Ramadan (fasting) in a state of major impurity without a wet dream, but on account of sexual intercourse and he would take a bath before dawn..","n":"'Aishah, and Umm Salamah","r":566},{"t":"The Messenger of Allah (ﷺ) was asked about observing As-Saum (the fast) on the tenth day of Muharram, and he replied, \"It is an expiation for the sins of the preceding year.\".","n":"Abu Qatadah","r":573},{"t":"The Messenger of Allah (ﷺ) said, \"He who observes As-Saum (the fasts) in the month of Ramadan, and also observes As-Saum for six days in the month of Shawwal, it is as if he has observed As-Saum for the whole year.\".","n":"Abu Ayyub","r":575},{"t":"The Messenger of Allah (ﷺ) said, \"Deeds of people are presented (to Allah) on Mondays and Thursdays. So I like that my actions be presented while I am fasting.\".","n":"Abu Hurairah","r":577},{"t":"My friend (the Messenger of Allah) (ﷺ) directed me to observe fast for three days in every month, to perform two Rak'ah (optional) Duha prayer at forenoon and to perform the Witr prayer before going to bed..","n":"Abu Hurairah","r":579},{"t":"The Messenger of Allah (ﷺ) said, \"Observing Saum (fasting) on three days of every month is equivalent to a full month's fasting.\".","n":"'Abdullah bin 'Amr bin Al-'As","r":581},{"t":"The Messenger of Allah (ﷺ) directed us to observe Saum (fasting) on the thirteenth, fourteenth and fifteenth of the (lunar) month..","n":"Qatadah bin Milhan","r":584},{"t":"The Prophet (ﷺ) said, \"He who provides a fasting person something with which to break his fast, will earn the same reward as the one who was observing the fast, without diminishing in any way the reward of the latter.\".","n":"Zaid bin Khalid Al-Juhani","r":586},{"t":"The Prophet (ﷺ) used to observe I'tikaf every year (during Ramadan) for ten days; in the year in which he passed away, he observed I'tikaf for twenty days..","n":"Abu Hurairah","r":591},{"t":"The Messenger of Allah (ﷺ) said, \"(The performance of) 'Umrah is an expiation for the sins committed between it and the previous 'Umrah; and the reward of Hajj Mabrur (i.e., one accepted) is nothing but Jannah.\".","n":"Abu Hurairah","r":596},{"t":"The Messenger of Allah (ﷺ) said, \"There is no day on which Allah sets free more slaves from Hell than He does on the Day of 'Arafah.\".","n":"'Aishah","r":598},{"t":"I was seven years old when I was taken to perform Hajj (pilgrimage). This was during the time the Messenger of Allah (ﷺ) performed the Hajjat-ul-Wada' (Farewell Pilgrimage)..","n":"As-Sai'b bin Yazid","r":602},{"t":"The Messenger of Allah (ﷺ) was asked: \"Which deed is the best?\" He (ﷺ) replied, \"Faith in Allah and Jihad (fighting, struggle) in the Cause of Allah.\".","n":"Abu Dharr","r":608},{"t":"I heard the Messenger of Allah (ﷺ) saying: \"Spending a day on the frontier in Allah's way is better than one thousand days in any other place.\".","n":"'Uthman","r":614},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Two eyes will never be touched by the fire of Hell; an eye which weeps out of Fear of Allah and an eye which spends the night in guarding in the Cause of Allah .\".","n":"Ibn 'Abbas","r":626},{"t":"The Messenger of Allah (ﷺ) said, \"He who supplicates Allah sincerely for martyrdom, Allah will elevate him to the station of the martyrs, even if he dies on his bed.\".","n":"Sahl bin Hunaif","r":642},{"t":"The Messenger of Allah (ﷺ) said, \"The martyr experiences no more pain in being slain than one of you experiences from the stinging of an ant.\".","n":"Abu Hurairah","r":644},{"t":"The Messenger of Allah (ﷺ) said, \"There is goodness in the forelocks of horses till the Day of Resurrection.\"","n":"Ibn 'Umar","r":649},{"t":"I heard the Messenger of Allah (ﷺ) saying from the pulpit, \"Prepare to meet them (the enemy) with as much strength as you can afford. Verily! Strength is in archery, strength is in archery, strength is in archery.\".","n":"'Uqbah bin 'Amir Al-Juhani","r":653},{"t":"The Messenger of Allah (ﷺ) said, \"He who learnt archery and then neglected it, is not from us.\" (Or said,) \"He has been guilty of disobedience (to Messenger of Allah).\".","n":"'Uqbah bin 'Amir Al-Juhani","r":655},{"t":"I heard the Messenger of Allah (ﷺ) saying: \"He who shoots an arrow for the sake of Allah, will have a reward equal to the emancipation of a slave.\".","n":"'Amr bin 'Abasah","r":658},{"t":"The Prophet (ﷺ) said, \"He who observes Saum (fasting) for a day in the Cause of Allah, Allah will keep his face from Hell-fire at a distance equivalent to that between heaven and the earth.\".","n":"Abu Umamah","r":661},{"t":"A man sought permission from the Messenger of Allah (ﷺ) to travel in the land. He (ﷺ) said to him, \"Travel for my people is Jihad in the Cause of Allah, glory be to Him.\".","n":"Abu Umamah","r":666},{"t":"When the Prophet (ﷺ) returned from the battle of Tabuk, people went out from Al-Madinah to meet him and I also met him with other children at Thaniyah-tul-Wada'..","n":"As-Sa'ib bin Yazid","r":668},{"t":"The Prophet (ﷺ) said, \"Fight the polytheists with your wealth, lives and tongues.\".","n":"Anas","r":670},{"t":"The Messenger of Allah (ﷺ) said, \"He who is killed while defending his property is a martyr.\".","n":"'Abdullah bin 'Amr bin Al-'As","r":676},{"t":"The Messenger of Allah (ﷺ) said, \"When your servant brings food for you and you do not seat him with you, you should at least give him a morsel or two out of it because he has prepared it himself.\".","n":"Abu Hurairah","r":682},{"t":"The Messenger of Allah (ﷺ) said, \"A slave who worships his Rubb (Allah) well and discharges efficiently and faithfully the duties which are assigned to him by his master, will have a double reward.\".","n":"Abu Musa Al-Ash'ari","r":685},{"t":"The Messenger of Allah (ﷺ) said, \"He who likes Allah to deliver him from the calamities of the Day of Resurrection, let him either give respite to a debtor or grant him remission (of loans) in straitened circumstances.\".","n":"Abu Qatadah","r":690},{"t":"The Messenger of Allah said, \"When Allah wishes good for someone, He bestows upon him the understanding of Deen.\".","n":"Mu'awiyah","r":697},{"t":"The Prophet (ﷺ) said to 'Ali (May Allah be pleased with him), \"By Allah, if a single person is guided by Allah through you, it will be better for you than a whole lot of red camels.\".","n":"Sahl bin Sa'd","r":700},{"t":"The Messenger of Allah (ﷺ) said, \"Allah makes the way to Jannah easy for him who treads the path in search of knowledge.\".","n":"Abu Hurairah","r":702},{"t":"The Messenger of Allah (ﷺ) said, \"The world, with all that it contains, is accursed except for the remembrance of Allah that which pleases Allah; and the religious scholars and seekers of knowledge.\".","n":"Abu Hurairah","r":705},{"t":"The Messenger of Allah (ﷺ) said, \"A believer never satisfies doing good until he reaches Jannah.\".","n":"Abu Sa'id Al-Khudri","r":707},{"t":"The Messenger of Allah (ﷺ) said, \"Any matter of importance which is not begun with Al-hamdu lillah (praise be to Allah) remains defective.\".","n":"Abu Hurairah","r":715},{"t":"I heard the Messenger of Allah (ﷺ) saying: \"Whoever supplicates Allah to exalt my mention, Allah will exalt his mention ten times.\".","n":"'Abdullah bin 'Amr bin Al-'As","r":718},{"t":"The Messenger of Allah (ﷺ) said, \"May his nose soil with dust in whose presence mention is made of me and he does not supplicate for me.\".","n":"Abu Hurairah","r":721},{"t":"The Messenger of Allah (ﷺ) said, \"Whenever someone greets me, Allah returns the soul to my body (in the grave) and I return his greeting.\".","n":"Abu Hurairah","r":723},{"t":"The Messenger of Allah (ﷺ) said, \"There are two statements that are light for the tongue to remember, heavy in the Scales and are dear to the Merciful: 'Subhan-Allahi wa bihamdihi, Subhan-Allahil-Azim .","n":"Abu Hurairah","r":729},{"t":"The Messenger of Allah (ﷺ) said, \"There are some words, the reciters of which will never be disappointed. These are: Tasbih","n":"Ka'b bin 'Ujrah","r":741},{"t":"The Messenger of Allah (ﷺ) used to recite in his bowing and prostration: \"Subbuhun Quddusun, Rabbul-mala'ikati war-ruh .","n":"'Aishah","r":747},{"t":"The Prophet (ﷺ) said, \"The similitude of one who remembers his Rubb and one who does not remember Him, is like that of the living and the dead.\".","n":"Abu Musa Al-Ash'ari","r":755},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"The best way to celebrate the remembrance of Allah is to say: La ilaha illallah (there is no true god except Allah).\".","n":"Jabir","r":758},{"t":"The Prophet (ﷺ) said, \"For him who says: 'Subhan-Allahi wa bi hamdihi (Allah is free from imperfection, and I begin with praising Him, and to Him),' a palm-tree will be planted in Jannah.\".","n":"Jabir","r":760},{"t":"The Messenger of Allah (ﷺ) used to remember Allah at all times..","n":"'Aishah","r":765},{"t":"The Messenger of Allah (ﷺ) used to supplicate when he went to bed at night: \"Bismik-Allahumma ahya wa amut (With Your Name, O Allah, I expire and return to life).\".","n":"Hudhaifah and Abu Dharr","r":779},{"t":"The Prophet (ﷺ) said, \"Du'a (supplication) is worship.\".","n":"An-Nu'man bin Bashir","r":786},{"t":"The Prophet (ﷺ) used to supplicate: \"Allahumma inni as'alukal-huda, wat-tuqa, wal-'afafa, wal-ghina (O Allah! I beseech You for guidance, piety, chastity and contentment).\".","n":"'Abdullah bin Mas'ud","r":789},{"t":"The Messenger of Allah (ﷺ) used to supplicate: \"Allahumma inni a'udhu bika minal-ajzi wal- kasali, wal-jubni wal-harami, wal-bukhli, wa a'udhu bika min 'adhabil- qabri, wa a'udhu bika min fitnatil-mahya wal-mamat .","n":"Anas","r":795},{"t":"The Messenger of Allah (ﷺ) used to supplicate: \"Allahumma inni a'udhu bika minal- ju'i, fa-innahu bi'sad-daji'u; wa a'udhu bika minal-khiyanati, fa- innaha bi'satil-bitanah' .","n":"Abu Hurairah","r":806},{"t":"The Messenger of Allah (ﷺ) said, \"Recite frequently: 'Ya Dhal-Jalali wal-Ikram! (O You, Possessor of glory and honour).\"'.","n":"Anas","r":812},{"t":"The Messenger of Allah (ﷺ) said, \"He who is favoured by another and says to his benefactor: `Jazak-Allah khairan (may Allah reward you well)' indeed praised (the benefactor) satisfactorily.'' .","n":"Usamah bin Zaid","r":817},{"t":"The Messenger of Allah (ﷺ) said, \"A slave becomes nearest to his Rubb when he is in prostration. So increase supplications in prostrations.\".","n":"Abu Hurairah","r":819},{"t":"The Prophet (ﷺ) said, \"He who believes in Allah and the Last Day must either speak good or remain silent.\".","n":"Abu Hurairah","r":832},{"t":"The Messenger of Allah (ﷺ) said, \"He whom Allah saves from the evil of that which is between his jaws and the evil of that which is between his legs will enter Jannah.\".","n":"Abu Hurairah","r":840},{"t":"The Messenger of Allah (ﷺ) said: \"The blood, honour and property of a Muslim is inviolable for another Muslim.\".","n":"Abu Hurairah","r":848},{"t":"A man sought permission for audience with the Prophet (ﷺ). He said, \"Give him permission but he is a bad member of his tribe.\".","n":"'Aishah  said","r":852},{"t":"The Messenger of Allah (ﷺ) said, \"The person who goes about with calumnies will never enter Jannah.\".","n":"Hudhaifah  said","r":857},{"t":"The Messenger of Allah (ﷺ) said, \"None of my Companions should convey to me anything regarding another because I desire to meet everyone of you with a clean heart.\".","n":"Ibn Mas'ud  said","r":860},{"t":"The Prophet (ﷺ) said, \"It is enough for a man to prove himself a liar when he goes on narrating whatever he hears.\".","n":"Abu Hurairah  said","r":868},{"t":"The Messenger of Allah (ﷺ) said: \"It does not befit a Siddiq (righteous Muslim) to frequently curse others.\"","n":"Abu Hurairah  said","r":873},{"t":"The Messenger of Allah (ﷺ) said, \"A true believer is not involved in taunting, or frequently cursing (others) or in indecency or abusing.\".","n":"Ibn Mas'ud","r":876},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"When any Muslim accuses another Muslim of sin or of disbelief, the reproach rebounds upon the one who utters it, if the other person is not deserving of it.\".","n":"Abu Dharr","r":881},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"He who accuses his slave of Zina will receive the punishment (Hadd) of slander on the Day of Resurrection, unless the accusation of Zina was true.\".","n":"Abu Hurairah  said","r":884},{"t":"The Messenger of Allah (ﷺ) said, \"A (true) Muslim is one from whose tongue and hand the Muslims are safe; and a Muhajir (Emigrant) is he who leaves the deeds which Allah has prohibited.\".","n":"'Abdullah bin 'Amr bin Al-'As","r":886},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"If you find faults with Muslims, you will corrupt them.\".","n":"Muawiyah  said","r":892},{"t":"The Messenger of Allah (ﷺ) said, \"Beware of suspicion, for suspicion is the worst of false tales.\".","n":"Abu Hurairah  said","r":894},{"t":"The Messenger of Allah (ﷺ) said, \"Two matters are signs of disbelief on the part of those who indulge in them: Defaming and speaking evil of a person's lineage, and wailing over the dead.\".","n":"Abu Hurairah  said","r":899},{"t":"The Messenger of Allah (ﷺ) prohibited the practice of Najsh..","n":"Ibn 'Umar  said","r":902},{"t":"The Messenger of Allah (ﷺ) said, \"He who deceives another's wife or his slave is none of us.\".","n":"Abu Hurairah  said","r":904},{"t":"The Messenger of Allah (ﷺ) said, \"Verily, Allah has revealed to me that you should adopt humility. So that no one may wrong another and no one may be disdainful and haughty towards another.\".","n":"'Iyad bin Himar  said","r":910},{"t":"I heard the Messenger of Allah (ﷺ) as saying, \"The Satan has despaired of being worshipped by those who engage in prayer in the Arabian Peninsula but (has not lost hope) in creating dissension among them.\".","n":"Jabir  said","r":915},{"t":"I heard the Prophet (ﷺ) saying, \"Whosoever forsakes his brother for a year is like one who sheds his blood.\".","n":"Abu Khirash Hadrad bin Abu Hadrad Al-Aslami  said","r":917},{"t":"The Messenger of Allah (ﷺ) forbade animals being tied (as targets)..","n":"Anas  said","r":923},{"t":"The Messenger of Allah (ﷺ) cursed the one who accepts Ar-Riba (the usury) and the one who pays it. . The narration in At-Tirmidhi adds: And the one who records it, and the two persons who stand witness to it.","n":"`Abdullah bin Mas`ud","r":936},{"t":"I asked the Messenger of Allah (ﷺ) about (the Islamic ruling on) accidental glance (i.e., at a woman one is not Islamically allowed to look at) and he ordered me to turn my eyes away..","n":"Jarir bin 'Abdullah  said","r":946},{"t":"The Messenger of Allah (ﷺ) cursed those men who are effeminate, and women who imitate men.Another narration is: The Messenger of Allah (ﷺ) cursed men who copy women and cursed women who copy men..","n":"Ibn 'Abbas  said","r":952},{"t":"I heard the Messenger of Allah (ﷺ) as saying: \"Do not eat with your left hand, because Satan eats and drinks with his left hand.\".","n":"Jabir  said","r":955},{"t":"I heard the Messenger of Allah (ﷺ) as saying: \"Jews and Christians do not dye their hair, so act differently from them.\".","n":"Abu Hurairah  said","r":957},{"t":"The Messenger of Allah (ﷺ) saw a boy, some portion of whose head was shaved and some of it was left out. He prohibited them from that and said, \"Shave the whole of it or leave the whole of it.\".","n":"Ibn 'Umar  said","r":960},{"t":"A similar narration was narrated on the authority of 'Aishah.","n":"","r":964},{"t":"The Prophet (ﷺ) said, \"Do not touch your private parts with your right hand while urinating, nor for washing or cleaning (your private parts); and do not breathe into the drinking vessel from which you drink.\".","n":"Abu Qatadah  said","r":969},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"When the lace of one of the shoes of any one of you is cut off, he should not walk with the other until he has got the lace repaired.\".","n":"Abu Hurairah  said","r":971},{"t":"The Prophet (ﷺ) said, \"Do not keep the fire burning in your homes when you go to bed.\".","n":"Ibn 'Umar  said","r":973},{"t":"The Prophet (ﷺ) said, \"The deceased is tortured in his grave for bewailing over him.\".","n":"'Umar bin Al-Khattab  said","r":978},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"He who allows (others) to wail over his death, will be punished for it on the Day of Resurrection.\".","n":"Al-Mughirah bin Shu'bah  said","r":981},{"t":"The Messenger of Allah (ﷺ) said, \"If the wailing woman does not repent before she dies, she will be made to stand on the Day of Resurrection wearing a garment of pitch and a garment of scabies (Allah knows the nature thereof).\".","n":"Abu Malik Al-Ash'ari  said","r":985},{"t":"The Messenger of Allah (ﷺ) said, \"He who acquires a branch of the knowledge of astrology, learns a branch of magic (of which he acquires more as long as) he continues to do so.\".","n":"Ibn 'Abbas  said","r":992},{"t":"The Messenger of Allah (ﷺ) said, \"Not the transmission of disease of one person to another and no evil omen, but I am pleased with good omens.\" He was asked: \"What is good omen?\" He replied, \"A good word.\".","n":"Anas  said","r":995},{"t":"The Messenger of Allah (ﷺ) said, \"Those who draw pictures will be punished on the Day of Resurrection; and it will be said to them: 'Breathe soul into what you have created.\"'.","n":"Ibn 'Umar  said","r":999},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Those who will receive the most severe punishment from Allah on the Day of Resurrection will be painters (of living objects).\".","n":"Ibn Mas'ud  said","r":1003},{"t":"The Messenger of Allah (ﷺ) said, \"The angels do not enter a house in which there is a dog or a portrait.\".","n":"Abu Talhah  said","r":1005},{"t":"The Messenger of Allah (ﷺ) said, \"He who keeps a dog other than one for guarding the fields or herds or hunting, will lose two Qirat every day out of his rewards.\".","n":"Ibn 'Umar  said","r":1009},{"t":"The Prophet (ﷺ) said, \"The bell is one of the musical instruments of Satan.\".","n":"Abu Hurairah  said","r":1012},{"t":"The Messenger of Allah (ﷺ) saw spittle or snot or sputum, sticking to the wall towards Qiblah and scratched it off..","n":"'Aishah  said","r":1015},{"t":"The Messenger of Allah (ﷺ) prohibited (us) from buying and selling in the mosque; (he also prohibited us from) making announcement in it about something lost and from reciting poems in it..","n":"'Amr bin Shu'aib on the authority of his grandfather  said","r":1020},{"t":"The Prophet (ﷺ) said, \"He who has eaten from this plant (i.e., garlic) should not approach us and should not offer Salat (prayer) along with us.\".","n":"Anas  said","r":1023},{"t":"The Prophet (ﷺ) forbade (us) from sitting with our legs drawn up to our belly (Ihtiba') during the Friday Khutbah (religious talk before the prayer)..","n":"Mu'adh bin Anas Al-Juhani  said","r":1026},{"t":"The Prophet (ﷺ) said, \"Allah has prohibited you from taking an oath by your fathers. He who must take an oath, may do so by swearing in the Name of Allah or he should remain silent.\".","n":"Ibn 'Umar  said","r":1028},{"t":"The Messenger of Allah (ﷺ) said, \"He who swears by Amanah (trust) is not one of us.\".","n":"Buraidah  said","r":1030},{"t":"The Messenger of Allah (ﷺ) said, \"When you swear an oath and consider something else to be better than it, make expiation for your oath and do the thing that is better.\".","n":"Abu Hurairah  said","r":1037},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Swearing produces a ready sale for a commodity, but blots out the blessing.\".","n":"Abu Hurairah  said","r":1041},{"t":"The Messenger of Allah (ﷺ) said, \"No one should ask in the Face of Allah for anything except Jannah.\".","n":"Jabir  said","r":1043},{"t":"The Messenger of Allah (ﷺ) said, \"Do not address a hypocrite with the title of chief, (or similar titles of respect) for even if he deserves this title you will invite Allah's Wrath by using it for him.\".","n":"Buraidah  said","r":1046},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"If somebody accuses another of disbelief or calls him the enemy of Allah, such an accusation will revert to him (the accuser) if the accused is innocent.\".","n":"Abu Dharr  said","r":1054},{"t":"The Messenger of Allah (ﷺ) said, \"Indecency does not leave anything untainted and decency does not leave anything ungraced and embellished.\".","n":"Anas  said","r":1056},{"t":"The Messenger of Allah (ﷺ) said, \"Verily, Allah dislikes an eloquent person who rolls his tongue as a cow rolls its tongue (while eating).\".","n":"'Abdullah bin 'Amr bin Al-As  said","r":1058},{"t":"The Messenger of Allah (ﷺ) said, \"No woman should touch another woman's body and then describe the details of her figure to her husband in such a manner as if he was looking at her.\".","n":"Ibn Mas'ud  said","r":1063},{"t":"The Prophet (ﷺ) said, \"Say not: 'What Allah wills and so-and-so wills', but say: 'What Allah wills, and then what so-and-so wills.\"'.","n":"Hudhaifah bin Yaman  said","r":1066},{"t":"Once, towards the end of his life, the Messenger of Allah (ﷺ) concluded the 'Isha' (night) prayer and said, \"After one hundred years from tonight none of the people on the surface of the earth will survive.\".","n":"Ibn 'Umar  said","r":1068},{"t":"The Messenger of Allah (ﷺ) said, \"It is not lawful for a woman to observe an optional Saum (fast) without the permission of her husband when he is at home. Nor should she allow anyone to enter his house without his permission.\".","n":"Abu Hurairah  said","r":1071},{"t":"We are prohibited from placing the hand on the side during As-Salat (the prayer)..","n":"Abu Hurairah  said","r":1073},{"t":"I asked the Messenger of Allah (ﷺ) about random looks in Salat (prayer), and he replied, \"It is something which Satan snatches from the slave's Salat.\".","n":"'Aishah  said","r":1076},{"t":"The Messenger of Allah (ﷺ) said, \"If the person who passes in front of a praying person, realizes the enormity of the sinfulness of this act, it will have been better for him to wait forty than to pass in front of him.\"","n":"Abul-Juhaim 'Abdullah bin Al-Harith  said","r":1079},{"t":"I heard the Messenger of Allah (ﷺ) as saying: \"None of you should observe fast on Friday except that he should observe fast either one day before it or one day after it.\".","n":"Abu Hurairah  said","r":1082},{"t":"The Prophet (ﷺ) prohibited observing continuous voluntary fasts beyond one day..","n":"Abu Hurairah and 'Aishah  said","r":1085},{"t":"The Messenger of Allah (ﷺ) said, \"It is much better for one of you to sit on a live coal, which will burn his clothes and get to his skin than to sit on a grave.\".","n":"Abu Hurairah  said","r":1087},{"t":"The Messenger of Allah (ﷺ) said, \"If a slave runs away from his master, his responsibility to him is absolved.\".","n":"Jarir bin Abdullah  said","r":1089},{"t":"The Messenger of Allah (ﷺ) forbade urinating into stagnant water..","n":"Jabir  said","r":1093},{"t":"The Messenger of Allah (ﷺ) said, \"Do not meet the merchandise till they arrive in the market.\".","n":"Ibn 'Umar  said","r":1097},{"t":"The Messenger of Allah (ﷺ) said, \"He who is presented with a flower of sweet basil should not reject it, because it is light in weight and pleasant in odour.\".","n":"Abu Hurairah  said","r":1107},{"t":"The Messenger of Allah (ﷺ) forbade travelling to the land of the enemy carrying the Qur'an..","n":"Ibn 'Umar  said","r":1115},{"t":"The Prophet (ﷺ) prohibited men from wearing saffron-dyed clothes..","n":"Anas  said","r":1119},{"t":"The Prophet (ﷺ) said, \"He who (falsely) attributes his fatherhood to anyone besides his real father, knowing that he is not his father, will be forbidden to enter Jannah.\".","n":"Sa'd bin Abu Waqqas  said","r":1123},{"t":"The Prophet (ﷺ) said, \"Allah, the Exalted, becomes angry, and His Anger is provoked when a person does what Allah has declared unlawful.\".","n":"Abu Hurairah  said","r":1127},{"t":"I heard the Prophet (ﷺ) saying, \"People will run away from Dajjal (the Antichrist) seeking shelter in the mountains.\".","n":"Umm Sharik","r":1134},{"t":"The Prophet (ﷺ) said, \"From your caliphs there will be one in the Last Days who will distribute wealth without counting it.\".","n":"Abu Sa'id Al-Khudri  said","r":1145},{"t":"We accompanied the Messenger of Allah (ﷺ) in seven expeditions, and we ate locusts..","n":"'Abdullah bin Abu 'Aufa  said","r":1154},{"t":"the Prophet (ﷺ) said, \"Allah marvels at those people who enter Jannah in chains.\".","n":"Abu Hurairah  said","r":1161},{"t":"The Prophet (ﷺ) said, \"One of the admonitions of the previous Prophets which has been conveyed to people is that if you have no modesty, you can do whatever you like.\".","n":"Abu Mas'ud Al-Ansari  said","r":1165},{"t":"The Messenger of Allah (ﷺ) said, \"Angels were created from light, jinns were created from a smokeless flame of fire, and 'Adam was created from that which you have been told (i.e., sounding clay like the clay of pottery).\".","n":"'Aishah","r":1167},{"t":"I came to visit the Prophet (ﷺ) while he was in the state of I'tikaf .","n":"Safiyyah bint Huyai , the Mother of the Believers, said","r":1170},{"t":"In the battle of Mu'tah, seven swords were broken in my hand, and all that remained with me was a Yemeni sword..","n":"Abu Sulaiman Khalid bin Al-Walid  said","r":1176},{"t":"The Prophet (ﷺ) said, \"If a person dies without observing Saum (fasts), his Wali should make it up on his behalf.\".","n":"'Aishah  said","r":1179},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"Truffle (edible fungus) is a species of Al-Manna and their water cures eye diseases.\"","n":"Sa'id bin Zaid","r":1189},{"t":"I heard the Messenger of Allah (ﷺ) saying, \"I swear by Allah that I seek Allah's Pardon and turn to Him in repentance more than seventy times a day.\".","n":"Abu Hurairah  said","r":1191},{"t":"The Messenger of Allah (ﷺ) said, \"A space in Jannah equal to the distance between the middle and the end of a bow will be better than all that upon which the sun rises and sets.\".","n":"Abu Hurairah  said","r":1209},{"t":"A'ishah (May Allah be pleased with her) narrated that the Prophet (ﷺ) said, \"There is no emigration after the conquest (of Makkah) but only Jihad ..","n":"","r":1220},{"t":"\"He who fights in order that the Word of Allah remains the supreme, is considered as fighting in the cause of Allah\"..","n":"Abu Musa Al-Ash'ari   that Messenger of Allah (ﷺ) was asked about who fights in the battlefield out of valour, or out of zeal, or out of hypocrisy, which of this is considered as fighting in the cause of Allah? He said","r":1225},{"t":"The Messenger of Allah (ﷺ) said: \"Turn you people in repentance to Allah and beg pardon of Him. I turn to Him in repentance a hundred times a day\"..","n":"Al-Agharr bin Yasar Al-Muzani  narrated that","r":1231},{"t":"The Prophet (ﷺ) said, \"Allah accepts a slave's repentance as long as the latter is not on his death bed (that is, before the soul of the dying person reaches the throat)\"..","n":"'Abdullah bin 'Umar bin Al-Khattab   that","r":1235},{"t":"The Messenger of Allah (ﷺ) said: \"He whom Allah intends good, He makes him to suffer from some affliction\"..","n":"Abu Hurairah   that","r":1256},{"t":"A man asked the Prophet (ﷺ) for an advice and he (ﷺ) said, \"Do not get angry\". The man repeated that several times and he replied, \"Do not get angry\"..","n":"Abu Hurairah","r":1265},{"t":"I remember (these words) from Messenger of Allah (ﷺ): \"Give up what is doubtful to you for that which is not doubtful; for truth is peace of mind and falsehood is doubt\"..","n":"Hasan bin 'Ali  said","r":1272},{"t":"Messenger of Allah (ﷺ) said, \"Fear Allah wherever you are, do good deeds after doing bad ones, the former will wipe out the latter, and behave decently towards people\"..","n":"Abu Dharr and Mu'adh bin Jabal   that","r":1278},{"t":"The Prophet (ﷺ) said, 'Verily, 'Allah, the Exalted, becomes angry, and His Anger is provoked when a person does what Allah has declared unlawful\"..","n":"Abu Hurairah","r":1281},{"t":"The Prophet (ﷺ) said, \"No man shall be asked for the reason of beating his wife\"..","n":"'Umar   that","r":1285},{"t":"Whenever the Prophet (ﷺ) stepped out of his house, he would say, \"Bismillah, tawakkaltu 'alallah. Allahumma inni a'udhu bika an adilla aw udalla, aw azilla aw uzalla, aw azlima aw uzlama, aw ajhala aw yujhala 'alayya\". \".","n":"Umm Salamah","r":1299},{"t":"Messenger of Allah (ﷺ) said, \"There are two blessings in which many people incur loss. (They are) health and free time (for doing good)\".","n":"Ibn Abbas","r":1314},{"t":"Messenger of Allah (ﷺ) said. \"The (Hell) Fire is surrounded with all kinds of desires and passions, while Jannah is surrounded with adversities.\".","n":"Abu Hurairah","r":1318},{"t":"Messenger of Allah (ﷺ) said, \"Three follow a dead body: members of his family, his possessions and his deeds. Two of them return and one remains with him. His family and his possessions return; his deeds remain with him\"..","n":"Anas","r":1321},{"t":"I heard Messenger of Allah (ﷺ) saying, \"Perform Salah more often. For every prostration that you perform before Allah will raise your position one degree and will remit one of your sins\"..","n":"Thauban  said","r":1324},{"t":"The Prophet (ﷺ) said, \"Allah excuses and grants forgiveness to a person until he attains the age of sixty years\"..","n":"Abu Hurairah","r":1329},{"t":"The Prophet (ﷺ) said, \"Every one will be raised in the condition in which he dies\"..","n":"Jabir  said","r":1333},{"t":"O Muslim women, never belittle any gift you give your neighbour even if it is a hoof of a sheep\"..","n":"Abu Hurairah","r":1341},{"t":"Messenger of Allah (ﷺ) said, \"When a slave of Allah suffers from illness or sets on a journey, he is credited with the equal of whatever good works he used to do when he was healthy or at home\"..","n":"Abu Musa Al-Ash'ari","r":1350},{"t":"Messenger of Allah (ﷺ) said, \"Allah will be pleased with His slave who praises Him (i.e., says Al-hamdu lillah) when he eats and praises Him when he drinks\"..","n":"Anas","r":1357},{"t":"I used to perform prayer with the Prophet (ﷺ) and his Salat was of a moderate length and his Khutbah too was moderate in length..","n":"Jabir bin Samurah","r":1365},{"t":"When Messenger of Allah (ﷺ) missed the optional night Salat (Tahajjud) due to pain or any other reason, he would perform twelve Rak'ah during the day time..","n":"'Aishah","r":1372},{"t":"Messenger of Allah (ﷺ) prohibited flicking pebbles by the index finger and the thumb; and he said, \"It does not kill a game animal nor does it inflict wound on the enemy, but breaks the tooth and gorges the eye\"..","n":"'Abdullah bin Mughaffal","r":1383},{"t":"Messenger of Allah (ﷺ) sent a detachment to Banu Lahyan tribe and remarked, \"Let one of every two men get ready to advance, and both will earn the same reward\"..","n":"Abu Sa'id Al-Khudri","r":1395},{"t":"The Prophet (ﷺ) said, \"No one of you becomes a true believer until he likes for his brother what he likes for himself\"..","n":"Anas","r":1400},{"t":"The Prophet (ﷺ) said, \"The best type of Jihad (striving in the way of Allah) is speaking a true word in the presence of a tyrant ruler.\".","n":"Abu Sa'id Al-Khudri","r":1411},{"t":"\"O you people! You recite this Verse: 'O you who believe! Take care of your ownselves. If you follow the (right) guidance .","n":"Abu Bakr As-Siddiq","r":1414},{"t":"Messenger of Allah (ﷺ) said, \"Whoever usurps unlawfully even a hand span of land a collar measuring seven times (this) land will be placed around his neck on the Day of Resurrection\"..","n":"'Aishah","r":1423},{"t":"Messenger of Allah (ﷺ) said, \"A believer continues to guard his Faith (and thus hopes for Allah's Mercy) so long as he does not shed blood unjustly\"..","n":"Ibn 'Umar","r":1437},{"t":"Messenger of Allah (ﷺ) said, \"The relationship of the believer with another believer is like (the bricks of) a building, each strengthens the other.\" He (ﷺ) illustrated this by interlacing the fingers of both his hands..","n":"Abu Musa","r":1439},{"t":"Messenger of Allah (ﷺ) said, \"He who is not merciful to people Allah will not be merciful to him.\".","n":"Jarir bin 'Abdullah","r":1444},{"t":"Messenger of Allah (ﷺ) said, \"I stand up to lead Salat with the intention of prolonging it. Then I hear the crying of an infant and I shorten the Salat lest I should make it burdensome for his mother\"..","n":"Abu Qatadah Al-Harith bin Rib'i","r":1448},{"t":"The Prophet (ﷺ) said, \"Allah will cover up on the Day of Resurrection the defects (faults) of the one who covers up the faults of the others in this world\"..","n":"Abu Hurairah","r":1457},{"t":"The Prophet (ﷺ) said to her, \"It is better for you to go back to your husband.\" She asked: \"O Messenger of Allah, do you order me to do so.\" He replied, \"I only intercede\" She then said: \"I have no need for him\"..","n":"Ibn 'Abbas ,  in connection with the case of Barirah  and her husband","r":1464},{"t":"Messenger of Allah (ﷺ) said, \"I will be like this in Jannah with the person who takes care of an orphan\". Messenger of Allah (ﷺ) raised his forefinger and middle finger by way of illustration..","n":"Sahl bin Sa'd","r":1479},{"t":"The Prophet (ﷺ) said, \"Whoever supports two girls till they attain maturity, he and I will come on the Day of Resurrection like this\". Messenger of Allah (ﷺ) joined his fingers illustrating this..","n":"Anas","r":1484},{"t":"Sa'd considered himself better than his inferiors, so the Prophet (ﷺ) said to him, \"You are given help and provision because of your weak ones\"..","n":"Mus'ab bin Sa'd bin Abu Waqqas","r":1488},{"t":"Messenger of Allah (ﷺ) said, \"The believers who show the most perfect Faith are those who have the best behaviour, and the best of you are those who are the best to their wives\"..","n":"Abu Hurairah","r":1495},{"t":"Messenger of Allah (ﷺ) said, \"When a man calls his wife to his bed, and she does not respond and he (the husband) spends the night angry with her, the angels curse her until morning\"..","n":"Abu Hurairah","r":1498},{"t":"Messenger of Allah (ﷺ) said, \"When a man calls his wife to satisfy his desire, she must go to him even if she is occupied with the oven\"..","n":"Abu 'Ali Talq bin 'Ali","r":1501},{"t":"Messenger of Allah (ﷺ) said, \"Any woman dies while her husband is pleased with her, she will enter Jannah\"..","n":"Umm Salamah","r":1503},{"t":"The Prophet (ﷺ) said, \"When someone spends on his family seeking his reward for it from Allah, it is counted as a charity from him\"..","n":"Abu Mas'ud Al-Badri","r":1510},{"t":"Messenger of Allah (ﷺ) said, \"Command your children to perform Salat (prayer) when they are seven years old, and beat them for (not offering) it when they are ten, and do not let (boys and girls) sleep together\"..","n":"'Amr bin Shu'aib  on his father's authority that his grandfather  said","r":1518},{"t":"Messenger of Allah (ﷺ) said, \"O Muslim women! No one of you should consider insignificant (a gift) to give to her neighbour even if it is (a gift of) the trotters of a sheep\"..","n":"Abu Hurairah","r":1523},{"t":"Messenger of Allah (ﷺ) said, \"No son can repay (the kindness shown by his father) unless he finds him a slave and buys him and emancipates him\"..","n":"Abu Hurairah","r":1530},{"t":"Messenger of Allah (ﷺ) said, \"He who desires ample provisions and his life be prolonged, should maintain good ties with his blood relations\". .","n":"Anas","r":1536},{"t":"The Prophet (ﷺ) said, \"(Of the) major sins are: to ascribe partners to Allah, disobey parents, murder someone, and to take a false oath (intentionally)\"..","n":"Abdullah bin 'Amr bin Al-'as","r":1554},{"t":"The Prophet (ﷺ) said, \"The finest act of goodness is that a person should treat kindly the loved ones of his father\".","n":"'Abdullah bin 'Umar","r":1558},{"t":"Messenger of Allah (ﷺ) said: \"He is not one of us who shows no mercy to younger ones and does not acknowledge the honour due to our elders\"..","n":"'Amr bin Shu'aib on the authority of his father who heard it from his father","r":1572},{"t":"Messenger of Allah (ﷺ) said, \"If a young man honours an older person on account of his age, Allah appoints someone to show reverence to him in his old age\".","n":"Anas bin Malik","r":1576},{"t":"I heard the Prophet (ﷺ) saying, \"Man follows his friend's religion, you should be careful who you take for friends\"..","n":"Abu Hurairah","r":1584},{"t":"The Prophet (ﷺ) said about the Ansar: \"Only a believer loves them, and only a hypocrite hates them. Allah loves him who loves them and Allah hates him who hates them\"..","n":"Al-Bara' bin 'Azib","r":1597},{"t":"Messenger of Allah (ﷺ) said, \"Hell will be brought on that Day (the Day of Resurrection) with seventy thousand bridles; and with every bridle will be seventy thousand angels, pulling it\"..","n":"Ibn Mas'ud","r":1614},{"t":"I heard Messenger of Allah (ﷺ) as saying, \"Mankind will stand before Allah, the Rubb of the worlds (on the Day of Resurrection), some of them will stand submerged in perspiration up to half of their ears\"..","n":"Ibn 'Umar","r":1617},{"t":"Messenger of Allah (ﷺ) said, \"By the One in Whose Hand my soul is, were you not to commit sins, Allah would replace you with a people who would commit sins and then seek forgiveness from Allah; and Allah would forgive them\"..","n":"Abu Hurairah","r":1639},{"t":"Messenger of Allah (ﷺ) said, \"The five daily Salat (prayers) are like a great river running by your door in which you take a bath five times a day.\".","n":"Jabir","r":1646},{"t":"Messenger of Allah (ﷺ) said, \"Allah is pleased with His slave who eats a meal and praises Him for it; and takes a drink and praises Him for it\"..","n":"Anas bin Malik","r":1653},{"t":"Messenger of Allah (ﷺ) said, \"Jannah is nearer to you than your shoelace, and so is the (Hell) Fire\"..","n":"Ibn Mas'ud","r":1662},{"t":"Messenger of Allah (ﷺ) sat on the pulpit and we sat around him. He said: \"What I am concerned most is the flourishment and the beauty of this world will be available to you\"..","n":"Abu Sa'id Al-Khudri","r":1674},{"t":"Messenger of Allah (ﷺ) said: \"Three (things) follow a dead person: Members of his family, his property and his deeds. Two of them return; and one remains with him. The people and his wealth return; his deeds remain with him\"..","n":"Anas","r":1677},{"t":"Messenger of Allah (ﷺ) said: \"If I had gold equal to Mount Uhud (in weight), it would not please me to pass three nights and I have a thing of it left with me, except what I retain for repayment of a debt\"..","n":"Abu Hurairah (May allah be pleased with him)","r":1682},{"t":"Messenger of Allah (ﷺ) said: \"The world is the believer's prison and the infidel's Jannah\"..","n":"Abu Hurairah (May allah be pleased with him)","r":1686},{"t":"Messenger of Allah (ﷺ) said, \"Were this world worth a wing of mosquito, He would not have given a drink of water to an infidel.\".","n":"Sahl bin Sa'd","r":1693},{"t":"Messenger of Allah (ﷺ) said: \"Do not crave for property lest you should be absorbed in the desire of worldly life.\".","n":"'Abdullah bin Mas'ud","r":1695},{"t":"Messenger of Allah (ﷺ) said, \"Two hungry wolves sent in the midst of a flock of sheep are no more destructive to them than a man's greed for wealth and fame is to his Deen.\".","n":"K'ab bin Malik","r":1701},{"t":"The Prophet (ﷺ) said, \"I looked into Jannah and saw that most of its dwellers are the poor; and I looked into Hell and saw that most of its inmates were women.\".","n":"Ibn 'Abbas and 'Imran bin Al-Husain","r":1704},{"t":"The Prophet (ﷺ) said, \"The most truthful statement a poet has ever made is the saying of Labid: Everything besides Allah is vain.\".","n":"Abu Hurairah","r":1706},{"t":"'Aishah (May Allah be pleased with her) showed us a sheet and a thick lower garment and said to us Messenger of Allah (ﷺ) was wearing them when he died..","n":"Abu Musa Al-Ash'ari","r":1715},{"t":"When Messenger of Allah (ﷺ) died, his armour was mortgaged with a Jew for thirty Sa' (measures) of barley..","n":"'Aishah","r":1720},{"t":"Messenger of Allah (ﷺ) said, \"Whosoever begins the day feeling family security and good health; and possessing provision for his day is as though he possesed the whole world.\".","n":"'Ubaidullah bin Mihsan Al-Ansari","r":1727},{"t":"The Messenger of Allah (ﷺ) went to bed hungry for several successive nights, nor did his family have a thing for supper for many consecutive nights; and their bread was mostly of barley..","n":"Ibn 'Abbas","r":1730},{"t":"The sleeves of the shirt of Messenger of Allah (ﷺ) reached his wrists..","n":"Asma' bint Yazid","r":1735},{"t":"the Messenger of Allah (ﷺ) said, \"Successful is the one who has entered the fold of Islam and is provided with sustenance which is sufficient for his needs, and Allah makes him content with what He has bestowed upon him.\"..","n":"'Abdullah bin 'Amr bin Al-as","r":1739},{"t":"The Prophet (ﷺ) said, \"If one of you would keep begging (of people) until he meets Allah (on the Day of Resurrection) his face will be without a shred of flesh.\".","n":"Ibn 'Umar","r":1746},{"t":"Messenger of Allah (ﷺ) said, \"Begging is a cut that a person inflicts upon his face; except for asking a ruler, or under the stress of circumstances from which there is no escape.\".","n":"Samurah bin Jundub","r":1749},{"t":"Messenger of Allah (ﷺ) said, \"It is better for anyone of you to carry a bundle of wood on his back and sell it than to beg of someone whether he gives him or refuses.\".","n":"Abu Hurairah","r":1756},{"t":"Messenger of Allah (ﷺ) said, \"(Prophet) Zakariyya (ﷺ) was a carpenter.\".","n":"Abu Hurairah","r":1758},{"t":"Messenger of Allah (ﷺ) said, \"Protect yourself from Hell-fire even by giving a piece of date as charity.\".","n":"'Adi bin Hatim","r":1762},{"t":"Messenger of Allah (ﷺ) said, \"Everyday two angels descend and one of them says, 'O Allah! Compensate (more) to the person who gives (in charity)'; while the other one says, 'O Allah! Destroy the one who withholds (charity, etc)\"..","n":"Abu Hurairah","r":1764},{"t":"A man asked Messenger of Allah (ﷺ), \"Which act in Islam is the best?\" He (ﷺ) replied, \"To feed (the poor and the needy) and to greet those whom you know and those you do not know.\".","n":"'Abdullah bin 'Amr bin Al-'as","r":1766},{"t":"Messenger of Allah (ﷺ) said, \"Envy is permitted only in two cases: A man whom Allah gives wealth, and he disposes of it rightfully, and a man to whom Allah gives knowledge which he applies and teaches it.\".","n":"Ibn Mas'ud","r":1787},{"t":"Messenger of Allah (ﷺ) said, \"Remember more often the destroyer of pleasures - death.\".","n":"Abu Hurairah","r":1795},{"t":"The Prophet (ﷺ) found a dry date-fruit lying in the way and said, \"Had it not been for fear of being from charity I would have eaten it.\".","n":"Anas bin Malik","r":1805},{"t":"I have retained these words of Messenger of Allah (ﷺ), \"Leave what causes you doubt and turn to what does not cause you doubt.\".","n":"Hasan bin 'Ali","r":1809},{"t":"Messenger of Allah (ﷺ) said, \"Every Prophet has tended sheep\". He was asked: \"And did you?\" He replied, \"Yes, I tended them for a few carats for the Makkans.\".","n":"Abu Hurairah","r":1816},{"t":"Messenger of Allah (ﷺ) said, \"Wealth does not diminish by giving Sadaqah (charity). Allah augments the honour of one who forgives; and one who serves another seeking the pleasure of Allah, Allah will exalt him in ranks.\".","n":"Abu Hurairah","r":1819},{"t":"The Prophet (ﷺ) said, \"Every Prophet has tended sheep.\" He was asked: \"And did you?\" He replied: \"Yes, I tended them for a few carats for the Makkans.\".","n":"Abu Hurairah","r":1825},{"t":"Messenger of Allah (ﷺ) said, \"Shall I not inform you about the inmates of Hell? It is every violent, impertinent and proud person.\".","n":"Harithah bin Wahab","r":1830},{"t":"Messenger of Allah (ﷺ) said, \"Allah, the Exalted, says: 'Honour is My Izar and Pride is My Cloak. Whoever vies with Me regarding one of them, shall be tormented.\"'.","n":"Abu Hurairah","r":1834},{"t":"The Messenger of Allah (ﷺ) was the best of all the people in behaviour..","n":"Anas","r":1837},{"t":"Messenger of Allah (ﷺ) did not indulge in loose talk nor did he like to listen to it. He used to say, \"The best of you is the best among you in conduct.\".","n":"'Abdullah bin 'Amr bin Al-'as","r":1841},{"t":"Messenger of Allah (ﷺ) said, \"The most perfect man in his faith among the believers is the one whose behaviour is most excellent; and the best of you are those who are the best to their wives.\".","n":"Abu Hurairah","r":1844},{"t":"Messenger of Allah (ﷺ) said to Ashaj Abdul-Qais (May Allah be pleased with him), \"You possess two qualities that Allah loves. These are clemency and tolerance.\".","n":"Ibn 'Abbas","r":1848},{"t":"The Prophet (ﷺ) said, \"Allah is Forbearer and He loves forbearance, and rewards for forbearance while He does not reward severity, and does not give for any thing besides it (forbearance).\"","n":"'Aishah","r":1850},{"t":"A bedouin urinated in the mosque and some people rushed to beat him up. The Prophet (ﷺ) said: \"Leave him alone and pour a bucket of water over it. You have been sent to make things easy and not to make them difficult.\".","n":"Abu Hurairah","r":1852},{"t":"Messenger of Allah (ﷺ) said, \"He who is deprived of forbearance and gentleness is, in fact, deprived of all good.\".","n":"Jarir bin 'Abdullah","r":1854},{"t":"Messenger of Allah (ﷺ) said, \"Shall I not tell you whom the (Hell) Fire is forbidden to touch? It is forbidden to touch a man who is always accessible, having polite and tender nature.\".","n":"Ibn Mas'ud","r":1858},{"t":"I heard the the Messenger of Allah (ﷺ) supplicating in my house: \"O Allah! Treat harshly those who rule over my Ummah with harshness, and treat gently those who rule over my Ummah with gentleness.\".","n":"'Aishah","r":1871},{"t":"The Messenger of Allah (ﷺ) said, \"The just will be seated upon pulpits of light.\" Those who are fair with regards to their judgement and their family and those who are under them.\".","n":"'Abdullah bin 'Amr bin Al-'as","r":1876},{"t":"The Prophet (ﷺ) said, \"It is obligatory upon a Muslim to listen (to the ruler) and obey whether he likes it or not, except when he is ordered to do a sinful thing; in such case, there is no obligation to listen or to obey.\".","n":"Ibn 'Umar","r":1879},{"t":"The Messenger of Allah (ﷺ) said, \"Hear and obey even if an Abyssinian slave whose head is like a raisin is placed in authority over you.\".","n":"Anas","r":1882},{"t":"Messenger of Allah (ﷺ) said, \"Whosoever obeys me, obeys Allah; and he who disobeys me, disobeys Allah; and whosoever obeys the Amir (leader), in fact, obeys me; and he who disobeys the Amir, in fact, disobeys me.\".","n":"Abu Hurairah","r":1887},{"t":"I heard Messenger of Allah (ﷺ) saying, \"He who insults the rulers Allah will insult him.\".","n":"Abu Bakrah","r":1889}];
(function(){
  const GOLD="#C9943E", TEXT="#E8E2D9", MUTED="#7A756E", BG="#0C0C0C";
  function serif(s,b){ try{return new Font(b?"Georgia-Bold":"Georgia",s);}catch(e){return b?Font.boldSystemFont(s):Font.systemFont(s);} }
  function mono(s,b){ try{return new Font(b?"Menlo-Bold":"Menlo",s);}catch(e){return b?Font.boldSystemFont(s):Font.systemFont(s);} }
  const now=new Date();
  const start=new Date(now.getFullYear(),0,0);
  const doy=Math.floor((now-start)/86400000);
  const H=HADITHS[doy % HADITHS.length] || HADITHS[0];
  const fam=(typeof config!=="undefined" && config.widgetFamily) || "medium";
  const isLock=fam.indexOf("accessory")===0;
  const w=new ListWidget();
  if(isLock){
    if(fam==="accessoryInline"){ w.addText("“"+H.t+"”"); }
    else { const t=w.addText(H.t); t.font=Font.systemFont(11); t.minimumScaleFactor=0.7; t.lineLimit=fam==="accessoryCircular"?3:4; }
  } else {
    w.backgroundColor=new Color(BG);
    w.setPadding(16,16,14,16);
    const eye=w.addText("HADITH OF THE DAY"); eye.font=mono(9,true); eye.textColor=new Color(GOLD); eye.textOpacity=0.9;
    w.addSpacer(fam==="large"?10:7);
    const body=w.addText("“"+H.t+"”"); body.font=serif(fam==="large"?19:14,false); body.textColor=new Color(TEXT); body.minimumScaleFactor=0.6; body.lineLimit=fam==="large"?12:6;
    w.addSpacer();
    const foot=w.addStack(); foot.centerAlignContent();
    const nm=foot.addText(H.n?("— "+H.n):"— Riyad as-Salihin"); nm.font=mono(10,false); nm.textColor=new Color(MUTED); nm.lineLimit=1; nm.minimumScaleFactor=0.7;
    foot.addSpacer();
    const rf=foot.addText("RS "+H.r); rf.font=mono(10,false); rf.textColor=new Color(MUTED);
  }
  try{ const d=new Date(); d.setHours(24,0,30,0); w.refreshAfterDate=d; }catch(e){}
  if(typeof Script!=="undefined"){ Script.setWidget(w); Script.complete(); }
  if(typeof config==="undefined" || !config.runsInWidget){ if(isLock && w.presentAccessoryRectangular) w.presentAccessoryRectangular(); else if(fam==="large") w.presentLarge(); else if(fam==="small") w.presentSmall(); else w.presentMedium(); }
})();
